  const overflowRoot = await projectRoot(); try { await bodies(overflowRoot, ["tdd"]); const path = await memory(overflowRoot, "overflow-adoption.md", memoryHeader("overflow-adoption")); const h = await harness(overflowRoot); const ctx: any = { sessionManager: { getBranch: () => [], getSessionId: () => "session", getLeafId: () => "anchor" }, ui: {} }; await h.hooks.get("session_start")({}, ctx); for (let index = 0; index <= PROVISIONAL_MAX_OBSERVATIONS; index++) { h.hooks.get("turn_end")({ message: { model: "model", usage: { input: index, output: 1, cacheRead: 0, cacheWrite: 0, cost: { total: 0 } } } }, ctx); await new Promise((done) => setImmediate(done)); } for (let attempt = 0; attempt < 2000 && !h.entries.some((entry: any) => entry.type === ASSOCIATION_ENTRY); attempt++) await new Promise((done) => setTimeout(done, 5)); const candidateId = h.entries.find((entry: any) => entry.type === ASSOCIATION_ENTRY)?.data.effortId; assert.equal(typeof candidateId, "string"); let settledUsage = 0; for (let attempt = 0; attempt < 2000; attempt++) { try { const resident = await events(overflowRoot, candidateId); settledUsage = resident.filter((event: any) => event.kind === "usage_observed").length; } catch {} if (settledUsage >= PROVISIONAL_MAX_OBSERVATIONS) break; await new Promise((done) => setTimeout(done, 5)); } assert.equal(settledUsage >= PROVISIONAL_MAX_OBSERVATIONS, true); await adopt(h.tools.get("awf_adopt_effort"), { memoryPath: path, effortId: "overflow-adoption", route: "unselected", phase: "implementation", workflow: "tdd" }, adoptionContext()); const candidate = await projectLocalLifecycle(h.ledger, candidateId); assert.equal(candidate.state, "abandoned"); assert.equal(candidate.associations.has("session"), false); const candidateEvents = await events(overflowRoot, candidateId); assert.equal(candidateEvents.some((event: any) => event.kind === "session_detached"), true); assert.equal(candidateEvents.some((event: any) => event.kind === "usage_observed"), true); assert.deepEqual((await events(overflowRoot, "overflow-adoption")).map((event: any) => event.kind), ["effort_adopted"]); await h.hooks.get("session_shutdown")({}, ctx); }
