test("provisional settlement retries custom persistence and partial ordered flush with deterministic identities", async () => {
  const root = await projectRoot(); try {
    assert.equal(PROVISIONAL_MAX_OBSERVATIONS, 256); assert.equal(PROVISIONAL_MAX_BYTES, 1024 * 1024);
    const ledger = defaultLedgerDependencies(join(root, ".pi/extensions/awf-dashboard/index.ts")); const durable = createLedgerWriter(ledger); let failAppend = true;
    const writer: any = { ...durable, append: async (event: any) => { if (event.observationId === "observation-b" && failAppend) { failAppend = false; throw new Error("partial flush"); } return durable.append(event); } };
    const persisted: any[] = []; let failCustom = true; const provisional = new ProvisionalIdentity(writer, ledger, "session", "candidate", { associate(value) { if (failCustom) { failCustom = false; throw new Error("custom entry"); } persisted.push(value); } });
    await provisional.observe("compaction_observed", { count: 1 }, undefined, "observation-a"); await provisional.observe("compaction_observed", { count: 2 }, undefined, "observation-b"); const buffered = provisional.snapshot(); assert.equal(buffered.count, 2); assert.ok(buffered.bytes > 0 && buffered.bytes < PROVISIONAL_MAX_BYTES);
    await assert.rejects(provisional.settleCandidate(), /custom entry/); assert.equal(provisional.snapshot().committed, true); assert.equal(provisional.snapshot().customPersisted, false);
    await assert.rejects(provisional.settleCandidate(), /partial flush/); assert.equal(provisional.snapshot().flushed, 1); const association = await provisional.settleCandidate(); assert.equal(association.effortId, "candidate"); assert.equal(persisted.length, 1); assert.equal(provisional.snapshot().flushed, 2);
    const stream = (await readFile(join(root, ".awf/metrics/efforts/candidate/sessions/session.jsonl"), "utf8")).trim().split("\n").map((line) => JSON.parse(line)); assert.deepEqual(stream.map((event: any) => event.kind), ["effort_created", "trajectory_started", "session_associated", "compaction_observed", "compaction_observed"]); assert.deepEqual(stream.slice(3).map((event: any) => event.observationId), ["observation-a", "observation-b"]); for (const event of stream) assert.match(event.eventId, /^provisional-event-[0-9a-f]{64}$/); for (const event of stream.slice(0, 3)) assert.match(event.idempotencyKey, /^provisional-[0-9a-f]{64}$/);
    await durable.shutdown();
  } finally { await rm(root, { recursive: true, force: true }); }
});

